mapper.select:
SELECT id, actor_id AS actorId, actor_type AS actorType, action,
       target_type AS targetType, target_id AS targetId, decision,
       reason_code AS reasonCode, correlation_id AS correlationId, ip,
       occurred_at AS occurredAt, ticket_scope AS ticketScope,
       capability, channel
FROM platform.platform_audit_event

     AND actor_id = #{actorId}::uuid
     AND action = #{action}
     AND target_type = #{targetType}
     AND target_id = #{targetId}::uuid
     AND occurred_at  >=  #{from}
     AND occurred_at  <=  #{to}

ORDER BY occurred_at DESC, id LIMIT #{limit}
